<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUidVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUserVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentityUserAccessor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityLoginProviderVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentityLoginProviderAccessor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentitySubjectAccessor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityCreatedAtVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentityCreatedAtAccessor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityVersionVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentityVersionAccessor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Formula\CreatedAtCalculator;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Event\UserFederatedIdentityCreateEvent;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Event\UserFederatedIdentityUpdateEvent;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Event\UserFederatedIdentityDeleteEvent;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;

class UserFederatedIdentity extends UserFederatedIdentityRef
{
    use UserFederatedIdentityUserAccessor;
    use UserFederatedIdentityLoginProviderAccessor;
    use UserFederatedIdentitySubjectAccessor;
    use UserFederatedIdentityCreatedAtAccessor;
    use UserFederatedIdentityVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        UserFederatedIdentityUidVO|string $uid,
        UserFederatedIdentityUserVO|UserRef $user,
        UserFederatedIdentityLoginProviderVO|TenantLoginProviderRef $loginProvider,
        UserFederatedIdentitySubjectVO|string $subject,
        UserFederatedIdentityCreatedAtVO|\DateTimeImmutable|null $createdAt = null,
        UserFederatedIdentityVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_user = UserFederatedIdentityUserVO::from($user);
        $this->_loginProvider = UserFederatedIdentityLoginProviderVO::from($loginProvider);
        $this->_subject = UserFederatedIdentitySubjectVO::from($subject);
        $this->_createdAt = null === $createdAt ? UserFederatedIdentityCreatedAtVO::empty() : UserFederatedIdentityCreatedAtVO::from($createdAt);
        $this->_version = null === $version ? UserFederatedIdentityVersionVO::empty() : UserFederatedIdentityVersionVO::from($version);
    }
    public function replace(UserFederatedIdentityAttributes $values): UserFederatedIdentity
    {
        $value = clone $this;
        $value->_user = $values->getUserOrCurrent($this->_user);
        $value->_loginProvider = $values->getLoginProviderOrCurrent($this->_loginProvider);
        $value->_subject = $values->getSubjectOrCurrent($this->_subject);
        $value->_createdAt = $values->getCreatedAtOrCurrent($this->_createdAt);
        $value->_version = $values->getVersionOrCurrent($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'createdAt'];
    }
    public static function create(UserFederatedIdentityAttributes $values): UserFederatedIdentity
    {
        $calculated = clone $values;
        $calculated->createdAt(CreatedAtCalculator::calculateCreatedAt());
        $value = $calculated->createNewInstance();
        $value->recordedEvents[] = new UserFederatedIdentityCreateEvent($value);
        return $value;
    }
    public function update(UserFederatedIdentityAttributes $values): UserFederatedIdentity
    {
        $calculated = clone $values;
        $calculated->createdAt(CreatedAtCalculator::calculateCreatedAt($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new UserFederatedIdentityUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): UserFederatedIdentity
    {
        $value = clone $this;
        $value->recordedEvents[] = new UserFederatedIdentityDeleteEvent($value);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['user'] = [ '$ref' => $this->getUser()->uid() ];
        $data['loginProvider'] = [ '$ref' => $this->getLoginProvider()->uid() ];
        $data['subject'] = $this->getSubject();
        $data['createdAt'] = $this->getCreatedAt();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): UserFederatedIdentityAttributes
    {
        return (new UserFederatedIdentityAttributes())
          ->uid($this->uid())
          ->user($this->_user)
          ->loginProvider($this->_loginProvider)
          ->subject($this->_subject)
          ->createdAt($this->_createdAt)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
